typedef float f32;
typedef signed short s16;

extern void fn_801252D8(int);

/*
 * NonMatching: assumes GQR2 retains the signed-16, scale-4 setup installed
 * by fn_801EF788. fn_801252D8(4) configures GQR6, not GQR2.
 * Retail loads all three packed components before storing the float vector.
 * Scaling in double is exact for every s16 input and avoids intermediate
 * float rounding in the scalar reconstruction.
 */
void fn_801270DC(f32* output, const s16* input)
{
    double x, y, z;

    fn_801252D8(4);
    x = (double)input[0] * 0.0625;
    y = (double)input[1] * 0.0625;
    z = (double)input[2] * 0.0625;
    output[0] = (f32)x;
    output[1] = (f32)y;
    output[2] = (f32)z;
}
